-- handwritten: runtime/client/mixins/Streaming.lua

do

local NewLoadSceneStartSphere, NewLoadSceneStop, IsNewLoadSceneActive, IsNewLoadSceneLoaded =
  NewLoadSceneStartSphere, NewLoadSceneStop, IsNewLoadSceneActive, IsNewLoadSceneLoaded
local P = fx.Promise

---@param position vector3
---@param radius? number
---@param timeoutMs? integer
---@return fx.Promise
statics.loadSceneAsync = function(position, radius, timeoutMs)
  -- one load scene at a time
  if IsNewLoadSceneActive() then NewLoadSceneStop() end
  if not NewLoadSceneStartSphere(position.x + 0.0, position.y + 0.0, position.z + 0.0, (radius or 50.0) + 0.0, 0) then
    return rt.fail("Streaming.loadSceneAsync: the load scene could not start")
  end
  return rt.waitUntil("Streaming.loadSceneAsync", IsNewLoadSceneLoaded, timeoutMs):next(function()
    NewLoadSceneStop()
  end, function(err)
    NewLoadSceneStop()
    return P.reject(err)
  end)
end

local RequestStreamedTextureDict, HasStreamedTextureDictLoaded = RequestStreamedTextureDict, HasStreamedTextureDictLoaded
local RequestIpl, IsIplActive = RequestIpl, IsIplActive

---@param dict string
local function requestTextureDict(dict) RequestStreamedTextureDict(dict, false) end
---@param v any
---@return boolean
local function isName(v) return type(v) == "string" and v ~= "" end

---@param dict string
---@param timeoutMs? integer
---@return fx.Promise<string>
statics.loadTextureDictAsync = function(dict, timeoutMs)
  return rt.load("Streaming.loadTextureDictAsync", "texture dictionary", requestTextureDict, HasStreamedTextureDictLoaded,
    isName, timeoutMs, dict)
end

